1	// Acceptance test for the change request:
2	//   "Let me filter projects by active, on hold or finished."
3	//
4	// The projects list page (projects-page, /projects), which lists every project, gains a control
5	// (data-testid="project-status-filter") that narrows the one list down to the projects at a SINGLE
6	// chosen stage. A project carries a STATUS — one of active, on hold, or finished (the same three
7	// stages the project-status cell already shows) — so choosing a stage leaves only the projects at
8	// that stage. Before a stage is chosen the list is unfiltered (every project shows). Choosing a
9	// DIFFERENT stage narrows to THAT stage's projects, and returning to "all statuses" brings every
10	// project back — so the filter is genuinely keyed on the chosen stage and not hardwired to one.
11	// Because a filter outlives a click (CLAUDE.md rule 4) the chosen stage lives in the URL and
12	// survives a fresh load. Filtering is a pure view concern: it records nothing.
13	//
14	// The contract for the control mirrors its toolbar siblings (invoice-status-filter / task-filter /
15	// project-tag-filter): it is a <select> in the projects toolbar with one option per stage (its label
16	// NAMING the stage — active / on hold / finished) plus a default "all statuses" option carrying an
17	// empty value (no stage => unfiltered). The test chooses a stage by finding the option whose label
18	// NAMES that stage (case-insensitively) and selecting it by that option's OWN value, so it binds to
19	// the stage's MEANING — not the exact value or capitalisation the control uses internally, the same
20	// way the sibling specs match the status cell by the stage word.
21	//
22	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
23	// (auditLines()). Data is arranged via resetAndSeed (the app's /__test__ endpoint): `clients`
24	// honours { id, name, email } and `projects` honours { id, name, clientId, status }.
25	import { test, expect, type Page, type Locator } from '@playwright/test';
26	import { resetAndSeed } from '../support/seed';
27	import { auditLines } from '../support/audit';
28	
29	// The three stages, each pinned by the word that names it (case-insensitive). Word boundaries keep
30	// them distinct; "on hold" tolerates any single separator (space / hyphen / underscore) so "On hold",
31	// "on-hold" and "ON_HOLD" all count. None of these words is a substring of another, nor of the
32	// default "all statuses" option label.
33	const ACTIVE = /\bactive\b/i;
34	const ON_HOLD = /\bon[\s_-]?hold\b/i;
35	const FINISHED = /\bfinished\b/i;
36	
37	const projectRows = (page: Page) => page.locator('[data-testid^="project-row-"]');
38	const statusOf = (page: Page, id: number): Locator =>
39	  page.getByTestId(`project-row-${id}`).getByTestId('project-status');
40	const nameOf = (page: Page, id: number): Locator =>
41	  page.getByTestId(`project-row-${id}`).getByTestId('project-name');
42	
43	// Two projects at EACH stage, so narrowing to one stage must drop the other four rows — a filter that
44	// merely hid a single row, or one hardwired to one stage, could not reproduce these results. All
45	// projects are left un-archived so the sibling show-archived toggle plays no part here. Project names
46	// are chosen so none contains a stage word (keeping the two concerns independent).
47	const SEED = {
48	  clients: [
49	    { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
50	    { id: 2, name: 'Globex', email: 'contact@globex.test' },
51	  ],
52	  projects: [
53	    { id: 1, name: 'Website Redesign', clientId: 1, status: 'ACTIVE' },
54	    { id: 2, name: 'Mobile App', clientId: 2, status: 'ON_HOLD' },
55	    { id: 3, name: 'Billing System', clientId: 1, status: 'FINISHED' },
56	    { id: 4, name: 'Internal Portal', clientId: 2, status: 'ACTIVE' },
57	    { id: 5, name: 'Marketing Hub', clientId: 1, status: 'ON_HOLD' },
58	    { id: 6, name: 'Data Warehouse', clientId: 2, status: 'FINISHED' },
59	  ],
60	};
61	
62	const ACTIVE_IDS = [1, 4];
63	const ON_HOLD_IDS = [2, 5];
64	const FINISHED_IDS = [3, 6];
65	const ALL_IDS = [1, 2, 3, 4, 5, 6];
66	
67	// The ids of the currently-rendered project rows, ascending (order is not what this feature is about).
68	async function visibleIds(page: Page): Promise<number[]> {
69	  return projectRows(page).evaluateAll((els) =>
70	    els
71	      .map((el) => Number(el.getAttribute('data-testid')!.replace('project-row-', '')))
72	      .sort((a, b) => a - b),
73	  );
74	}
75	
76	// Choose a stage in the filter. The option is found by the stage WORD in its label and selected by
77	// that option's own value, so the stage is pinned by meaning, not by an exact value/capitalisation.
78	async function chooseStage(page: Page, word: RegExp): Promise<void> {
79	  const filter = page.getByTestId('project-status-filter');
80	  await expect(filter).toBeVisible();
81	  const value = await filter
82	    .locator('option')
83	    .filter({ hasText: word })
84	    .first()
85	    .evaluate((el: HTMLOptionElement) => el.value);
86	  await filter.selectOption(value);
87	}
88	
89	// Return the filter to "all statuses": the default option carries no stage, so it has an empty value
90	// (an empty value clears the URL key, leaving the list unfiltered) — same mechanism as the siblings.
91	async function chooseAllStatuses(page: Page): Promise<void> {
92	  await page.getByTestId('project-status-filter').selectOption('');
93	}
94	
95	test.describe('Filter projects by status', () => {
96	  test('the projects page offers a status filter and lists every project before one is chosen', async ({
97	    page,
98	  }) => {
99	    await resetAndSeed(SEED);
100	
101	    await page.goto('/projects');
102	    await expect(page.getByTestId('projects-page')).toBeVisible();
103	
104	    // The new filter control is present on the page.
105	    await expect(page.getByTestId('project-status-filter')).toBeVisible();
106	
107	    // Before any stage is chosen the list is unfiltered: every seeded project is shown.
108	    await expect(page.getByTestId('projects-table')).toBeVisible();
109	    await expect(projectRows(page)).toHaveCount(ALL_IDS.length);
110	    expect(await visibleIds(page)).toEqual(ALL_IDS);
111	
112	    // Reading the list records nothing.
113	    expect(auditLines()).toEqual([]);
114	  });
115	
116	  test('choosing "active" narrows the list to only the active projects', async ({ page }) => {
117	    await resetAndSeed(SEED);
118	
119	    await page.goto('/projects');
120	    // Precondition: everything is listed, so the narrowing below is a real effect of the filter.
121	    await expect(projectRows(page)).toHaveCount(ALL_IDS.length);
122	
123	    await chooseStage(page, ACTIVE);
124	
125	    // Only the two active projects remain; every on-hold and finished project has dropped out.
126	    await expect(projectRows(page)).toHaveCount(ACTIVE_IDS.length);
127	    expect(await visibleIds(page)).toEqual(ACTIVE_IDS);
128	    for (const id of ACTIVE_IDS) {
129	      await expect(page.getByTestId(`project-row-${id}`)).toBeVisible();
130	      await expect(statusOf(page, id)).toHaveText(ACTIVE);
131	    }
132	    for (const id of [...ON_HOLD_IDS, ...FINISHED_IDS]) {
133	      await expect(page.getByTestId(`project-row-${id}`)).toHaveCount(0);
134	    }
135	
136	    // The surviving rows still carry their real data — narrowing filters the list, it does not blank it.
137	    await expect(nameOf(page, 1)).toHaveText('Website Redesign');
138	    await expect(nameOf(page, 4)).toHaveText('Internal Portal');
139	  });
140	
141	  test('the filter is keyed on the chosen stage: each stage narrows to its own projects', async ({
142	    page,
143	  }) => {
144	    await resetAndSeed(SEED);
145	
146	    await page.goto('/projects');
147	
148	    // On-hold projects only.
149	    await chooseStage(page, ON_HOLD);
150	    await expect(projectRows(page)).toHaveCount(ON_HOLD_IDS.length);
151	    expect(await visibleIds(page)).toEqual(ON_HOLD_IDS);
152	    for (const id of ON_HOLD_IDS) {
153	      await expect(statusOf(page, id)).toHaveText(ON_HOLD);
154	    }
155	
156	    // Switching to "finished" narrows to a DIFFERENT set — proof the filter follows the chosen stage
157	    // and is not hardwired to one (the on-hold projects are gone, the finished ones are now shown).
158	    await chooseStage(page, FINISHED);
159	    await expect(projectRows(page)).toHaveCount(FINISHED_IDS.length);
160	    expect(await visibleIds(page)).toEqual(FINISHED_IDS);
161	    for (const id of FINISHED_IDS) {
162	      await expect(statusOf(page, id)).toHaveText(FINISHED);
163	    }
164	
165	    // Returning to "all statuses" brings every project back.
166	    await chooseAllStatuses(page);
167	    await expect(projectRows(page)).toHaveCount(ALL_IDS.length);
168	    expect(await visibleIds(page)).toEqual(ALL_IDS);
169	  });
170	
171	  test('the chosen stage survives a fresh load, and filtering records nothing', async ({ page }) => {
172	    await resetAndSeed(SEED);
173	
174	    await page.goto('/projects');
175	    await chooseStage(page, FINISHED);
176	    await expect(projectRows(page)).toHaveCount(FINISHED_IDS.length);
177	    expect(await visibleIds(page)).toEqual(FINISHED_IDS);
178	
179	    // Reloading re-reads the page; the chosen stage is still in effect and the same rows come back
180	    // (the filter lives in the URL, not in throwaway component state).
181	    await page.reload();
182	    await expect(page.getByTestId('projects-page')).toBeVisible();
183	    await expect(projectRows(page)).toHaveCount(FINISHED_IDS.length);
184	    expect(await visibleIds(page)).toEqual(FINISHED_IDS);
185	
186	    // Filtering is a pure view concern: narrowing the list (and reloading) is not a change to any
187	    // project, so nothing is appended to the audit file.
188	    expect(auditLines()).toEqual([]);
189	  });
190	});
191

